  "trans.conselho.title": "Consejo Fiscal",
  "trans.conselho.p1": "El Consejo Fiscal de ACURABRASIL es responsable de la fiscalización contable, financiera, presupuestaria, operacional y patrimonial de la entidad, en conformidad con el estatuto social y la legislación aplicable a las OSCIP.",
  "trans.conselho.p2": "Para información sobre la composición del Consejo Fiscal o solicitud de documentos, entre en <a href=\"/contato\" style=\"color: var(--azul-institucional); font-weight: 500;\">contacto con nosotros</a>.",
  "trans.cadastro.title": "Información Registral",
  "trans.cadastro.razao.title": "Razón Social",
  "trans.cadastro.razao.value": "ACURABRASIL — Asociación Brasil por la Cura",
  "trans.cadastro.cnpj.title": "CNPJ",
  "trans.cadastro.cnpj.value": "30.350.850/0001-80",
